std::random_device rd;
std::mt19937 gen(rd());
const double kB = 1.0; // Boltzmann constant (assuming units where kB=1)

// Calculate probability of collision for each particle
double collisionProb = collisionFreq * dt;

// For each particle, decide whether to reassign velocity
for (size_t i = 0; i < velocities.size(); ++i) {
    // Generate random number between 0 and 1
    std::uniform_real_distribution<double> uniform_dist(0.0, 1.0);
    double rand_val = uniform_dist(gen);

    // If collision occurs, reassign velocity from Maxwell-Boltzmann distribution
    if (rand_val < collisionProb) {
        double mass = masses[i];
        double stddev = std::sqrt(kB * targetTemp / mass);

        // Generate normally distributed random numbers for each velocity component
        std::normal_distribution<double> normal_dist(0.0, stddev);
        velocities[i].x = normal_dist(gen);
        velocities[i].y = normal_dist(gen);
        velocities[i].z = normal_dist(gen);
    }
}

